questions.query:
explore {
  dimensions { ship_mode: lineitem.ship_mode }
  measures {
    line_count: line_count,
    late_share: (lineitem | count_if(lineitem.receipt_date > lineitem.commit_date)) / line_count,
  }
  sorts { ship_mode asc }
}

explore {
  dimensions { supplier_region_name: supplier_region.supplier_region_name }
  measures {
    returned_share: (lineitem | count_if(lineitem.return_flag == 'R')) / line_count,
  }
  sorts { supplier_region_name asc }
}

explore {
  dimensions { ship_mode: lineitem.ship_mode }
  measures { total_quantity: total_quantity }
  filters { lineitem.ship_date matches @(1997-01-01 - 1997-12-31) }
  sorts { ship_mode asc }
}

explore {
  dimensions { supplier_region_name: supplier_region.supplier_region_name }
  measures { total_available_qty: total_available_qty }
  sorts { supplier_region_name asc }
}

explore {
  dimensions { order_status: orders.order_status }
  measures { order_count: order_count }
  sorts { order_status asc }
}

explore {
  dimensions { ship_mode: lineitem.ship_mode }
  measures { avg_transit_days: lineitem | avg(date_diff('day', lineitem.ship_date, lineitem.receipt_date)) }
  filters { lineitem.ship_date matches @(1997-01-01 - 1997-12-31) }
  sorts { ship_mode asc }
}

explore {
  dimensions { supplier_name: supplier.supplier_name }
  measures {
    line_count: line_count,
    late_share: (lineitem | count_if(lineitem.receipt_date > lineitem.commit_date)) / line_count,
  }
  filters { lineitem.receipt_date matches @(1996-01-01 - 1997-12-31) }
  having { line_count > 99 }
  sorts { late_share desc, supplier_name asc }
  limit: 10
}

explore {
  dimensions { order_priority: orders.order_priority }
  measures {
    line_count: line_count,
    late_share: (lineitem | count_if(lineitem.receipt_date > lineitem.commit_date)) / line_count,
  }
  filters { orders.order_date matches @(1995-01-01 - 1995-12-31) }
  sorts { order_priority asc }
}

explore {
  dimensions { ship_month: lineitem.ship_date | month() }
  measures {
    late_share: (lineitem | count_if(lineitem.receipt_date > lineitem.commit_date)) / line_count,
  }
  filters { lineitem.ship_date matches @(1997-01-01 - 1997-12-31) }
  sorts { ship_month asc }
}

explore {
  dimensions { manufacturer: part.manufacturer }
  measures {
    returned_qty_share: (total_quantity | where(lineitem.return_flag == 'R')) / total_quantity,
  }
  filters { lineitem.receipt_date matches @(1994-01-01 - 1994-12-31) }
  sorts { manufacturer asc }
}

dimension lineitem.is_late = lineitem.receipt_date > lineitem.commit_date;
explore {
  dimensions { supplier_nation_name: supplier_nation.supplier_nation_name }
  measures {
    late_line_count: line_count,
    avg_days_late: lineitem | avg(date_diff('day', lineitem.commit_date, lineitem.receipt_date)),
  }
  filters {
    lineitem.ship_date matches @(1996-01-01 - 1996-12-31),
    lineitem.is_late is true,
  }
  sorts { supplier_nation_name asc }
}

explore {
  dimensions { part_type: part.part_type }
  measures {
    total_available_qty: total_available_qty,
    total_quantity_1997: total_quantity | where(orders.order_date matches @(1997-01-01 - 1997-12-31)),
    cover_ratio: total_available_qty / (total_quantity | where(orders.order_date matches @(1997-01-01 - 1997-12-31))),
  }
  filters { part.part_type like '%BRASS%' }
  sorts { part_type asc }
}

dimension lineitem.is_late = lineitem.receipt_date > lineitem.commit_date;
explore {
  dimensions { ship_mode: lineitem.ship_mode }
  measures {
    late_line_count: line_count,
    shipped_late_share: (lineitem | count_if(lineitem.ship_date > lineitem.commit_date)) / line_count,
    transit_late_share: (lineitem | count_if(lineitem.ship_date <= lineitem.commit_date)) / line_count,
  }
  filters {
    lineitem.ship_date matches @(1997-01-01 - 1997-12-31),
    lineitem.is_late is true,
  }
  sorts { ship_mode asc }
}

metric late_share = (lineitem | count_if(lineitem.receipt_date > lineitem.commit_date)) / line_count;
metric late_share_1995 = late_share | where(lineitem.ship_date matches @(1995-01-01 - 1995-12-31));
metric late_share_1996 = late_share | where(lineitem.ship_date matches @(1996-01-01 - 1996-12-31));
metric lines_1995 = line_count | where(lineitem.ship_date matches @(1995-01-01 - 1995-12-31));
metric lines_1996 = line_count | where(lineitem.ship_date matches @(1996-01-01 - 1996-12-31));
explore {
  dimensions { supplier_name: supplier.supplier_name }
  measures {
    late_share_1995: late_share_1995,
    late_share_1996: late_share_1996,
    late_share_change: late_share_1996 - late_share_1995,
  }
  having { lines_1995 > 49, lines_1996 > 49 }
  sorts { late_share_change desc, supplier_name asc }
  limit: 10
}

dimension orders.late_lines_in_order = coalesce(lineitem | count_if(lineitem.receipt_date > lineitem.commit_date) | dimensionalize(orders.order_key), 0);
explore {
  dimensions { late_lines_in_order: orders.late_lines_in_order }
  measures { order_count: order_count }
  filters {
    orders.order_status == 'F',
    orders.order_date matches @(1994-01-01 - 1994-12-31),
  }
  sorts { late_lines_in_order asc }
}

metric late_share = (lineitem | count_if(lineitem.receipt_date > lineitem.commit_date)) / line_count;
metric nation_rank = rank(
  order: late_share | desc(),
  order: supplier_nation | min(supplier_nation.supplier_nation_name) | asc(),
  partition: supplier_region.supplier_region_name
);
explore {
  dimensions {
    supplier_region_name: supplier_region.supplier_region_name,
    supplier_nation_name: supplier_nation.supplier_nation_name,
  }
  measures { late_share: late_share }
  filters { lineitem.ship_date matches @(1997-01-01 - 1997-12-31) }
  having { nation_rank == 1 }
  sorts { supplier_region_name asc }
}

dimension part.min_supply_cost = partsupp | min(partsupp.supply_cost) | dimensionalize(part.part_name, part.manufacturer);
explore {
  dimensions { manufacturer: part.manufacturer }
  measures {
    cheapest_source_qty_share: (total_quantity | where(partsupp.supply_cost == part.min_supply_cost)) / total_quantity,
  }
  filters { lineitem.ship_date matches @(1997-01-01 - 1997-12-31) }
  sorts { manufacturer asc }
}

explore {
  dimensions { order_year: orders.order_date | year() }
  measures { revenue: revenue }
  sorts { order_year asc }
}

explore {
  dimensions { market_segment: customer.market_segment }
  measures { avg_discount: avg_discount }
  sorts { market_segment asc }
}

explore {
  measures {
    gross_sales: gross_sales,
    revenue: revenue,
    discount_amount: gross_sales - revenue,
  }
  filters { orders.order_date matches @(1996-01-01 - 1996-12-31) }
}

explore {
  dimensions { order_priority: orders.order_priority }
  measures { avg_order_value: avg_order_value }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { order_priority asc }
}

explore {
  dimensions { customer_region_name: customer_region.customer_region_name }
  measures { revenue: revenue }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { customer_region_name asc }
}

explore {
  dimensions { order_year: orders.order_date | year() }
  measures {
    revenue: revenue,
    revenue_growth: revenue / (revenue | relative_period(orders.order_date, interval(-1 year))) - 1,
  }
  filters { orders.order_date matches @(1993-01-01 - 1997-12-31) }
  sorts { order_year asc }
}

metric supply_cost_amount = lineitem | sum(partsupp.supply_cost * lineitem.quantity);
explore {
  dimensions { supplier_region_name: supplier_region.supplier_region_name }
  measures {
    revenue: revenue,
    margin: revenue - supply_cost_amount,
    margin_rate: (revenue - supply_cost_amount) / revenue,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { supplier_region_name asc }
}

metric supply_cost_amount = lineitem | sum(partsupp.supply_cost * lineitem.quantity);
explore {
  dimensions { brand: part.brand }
  measures { margin: revenue - supply_cost_amount }
  filters { orders.order_date matches @(1996-01-01 - 1996-12-31) }
  sorts { margin desc, brand asc }
  limit: 10
}

explore {
  dimensions { order_month: orders.order_date | month() }
  measures { revenue: revenue }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { order_month asc }
}

explore {
  dimensions { discount: lineitem.discount }
  measures { line_count: line_count, revenue: revenue }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { discount asc }
}

explore {
  dimensions { order_year: orders.order_date | year() }
  measures {
    returned_revenue: coalesce(revenue | where(lineitem.return_flag == 'R'), 0),
    returned_revenue_share: coalesce(revenue | where(lineitem.return_flag == 'R'), 0) / revenue,
  }
  filters { orders.order_date matches @(1992-01-01 - 1997-12-31) }
  sorts { order_year asc }
}

metric revenue_h1_1997 = revenue | where(orders.order_date matches @(1997-01-01 - 1997-06-30));
metric revenue_h1_1998 = revenue | where(orders.order_date matches @(1998-01-01 - 1998-06-30));
explore {
  dimensions { customer_region_name: customer_region.customer_region_name }
  measures {
    revenue_h1_1997: revenue_h1_1997,
    revenue_h1_1998: revenue_h1_1998,
    revenue_growth: revenue_h1_1998 / revenue_h1_1997 - 1,
  }
  sorts { customer_region_name asc }
}

metric customer_rank = rank(
  order: revenue | desc(),
  order: customer | min(customer.customer_key) | asc(),
  partition: []
);
metric top100_customers = unique(customer.customer_key) | filter(customer_rank < 101);
metric top100_revenue = revenue | where(customer.customer_key in (top100_customers | select(customer.customer_key)));
explore {
  measures {
    top100_revenue: top100_revenue,
    total_revenue: revenue,
    top100_share: top100_revenue / revenue,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
}

metric rank_in_segment = rank(
  order: revenue | desc(),
  order: customer_nation | min(customer_nation.customer_nation_name) | asc(),
  partition: customer.market_segment
);
explore {
  dimensions {
    market_segment: customer.market_segment,
    customer_nation_name: customer_nation.customer_nation_name,
  }
  measures {
    revenue: revenue,
    segment_revenue_share: revenue / (revenue | exclude_grains(customer_nation.customer_nation_name)),
    rank_in_segment: rank_in_segment,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  having { rank_in_segment < 4 }
  sorts { market_segment asc, rank_in_segment asc }
}

dimension lineitem.line_margin = lineitem.extended_price * (1 - lineitem.discount) - partsupp.supply_cost * lineitem.quantity;
explore {
  dimensions { brand: part.brand }
  measures {
    below_cost_line_share: (lineitem | count_if(lineitem.line_margin < 0)) / line_count,
    below_cost_margin: coalesce(lineitem | where(lineitem.line_margin < 0) | sum(lineitem.line_margin), 0),
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { brand asc }
}

metric aov_1996 = avg_order_value | where(orders.order_date matches @(1996-01-01 - 1996-12-31));
metric aov_1997 = avg_order_value | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
metric orders_1996 = order_count | where(orders.order_date matches @(1996-01-01 - 1996-12-31));
metric orders_1997 = order_count | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
explore {
  dimensions { clerk: orders.clerk }
  measures {
    avg_order_value_1996: aov_1996,
    avg_order_value_1997: aov_1997,
    avg_order_value_change: aov_1997 - aov_1996,
  }
  having { orders_1996 > 99, orders_1997 > 99 }
  sorts { avg_order_value_change desc, clerk asc }
  limit: 10
}

explore {
  dimensions {
    customer_region_name: customer_region.customer_region_name,
    order_quarter: orders.order_date | quarter(),
  }
  measures {
    revenue: revenue,
    revenue_yoy_growth: revenue / (revenue | relative_period(orders.order_date, interval(-1 year))) - 1,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { customer_region_name asc, order_quarter asc }
}

explore {
  dimensions { market_segment: customer.market_segment }
  measures { customer_count: customer_count }
  sorts { market_segment asc }
}

explore {
  dimensions { manufacturer: part.manufacturer }
  measures { revenue: revenue }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { manufacturer asc }
}

explore {
  dimensions { customer_region_name: customer_region.customer_region_name }
  measures { customer_count: customer_count }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { customer_region_name asc }
}

explore {
  dimensions { market_segment: customer.market_segment }
  measures { order_count: order_count }
  filters { orders.order_date matches @(1996-01-01 - 1996-12-31) }
  sorts { market_segment asc }
}

explore {
  dimensions { market_segment: customer.market_segment }
  measures { avg_order_value: avg_order_value }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { market_segment asc }
}

dimension part.container_size = split_part(part.container, ' ', 1);
explore {
  dimensions { container_size: part.container_size }
  measures {
    revenue: revenue,
    revenue_share: revenue / (revenue | exclude_grains(part.container_size)),
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { container_size asc }
}

metric revenue_1996 = revenue | where(orders.order_date matches @(1996-01-01 - 1996-12-31));
metric revenue_1997 = revenue | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
explore {
  dimensions { customer_nation_name: customer_nation.customer_nation_name }
  measures {
    revenue_1996: revenue_1996,
    revenue_1997: revenue_1997,
    revenue_growth: revenue_1997 / revenue_1996 - 1,
  }
  sorts { revenue_growth desc, customer_nation_name asc }
  limit: 10
}

dimension customer.orders_1997 = order_count | where(orders.order_date matches @(1997-01-01 - 1997-12-31)) | dimensionalize(customer.customer_key);
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    customer_count: customer_count,
    repeat_customer_share: (customer_count | where(customer.orders_1997 > 1)) / customer_count,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { market_segment asc }
}

explore {
  dimensions { brand: part.brand }
  measures { revenue: revenue }
  filters {
    orders.order_date matches @(1997-01-01 - 1997-12-31),
    customer.market_segment == 'AUTOMOBILE',
  }
  sorts { revenue desc, brand asc }
  limit: 5
}

explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    negative_balance_revenue_share: (revenue | where(customer.account_balance < 0)) / revenue,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { market_segment asc }
}

explore {
  dimensions { customer_region_name: customer_region.customer_region_name }
  measures {
    revenue: revenue,
    customer_count: customer_count,
    revenue_per_customer: revenue / customer_count,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { customer_region_name asc }
}

dimension customer.first_order_date = orders | min(orders.order_date) | dimensionalize(customer.customer_key);
dimension customer.first_order_year = date_part('year', customer.first_order_date);
dimension orders.in_year_after_first = date_part('year', orders.order_date) == customer.first_order_year + 1;
dimension customer.orders_year_after_first = order_count | where(orders.in_year_after_first is true) | dimensionalize(customer.customer_key);
explore {
  dimensions { first_order_year: customer.first_order_year }
  measures {
    customer_count: customer_count,
    retained_next_year_share: (customer_count | where(customer.orders_year_after_first > 0)) / customer_count,
  }
  filters { customer.first_order_year in [1992, 1993, 1994, 1995, 1996] }
  sorts { first_order_year asc }
}

dimension customer.orders_1996 = order_count | where(orders.order_date matches @(1996-01-01 - 1996-12-31)) | dimensionalize(customer.customer_key);
dimension customer.orders_1997 = order_count | where(orders.order_date matches @(1997-01-01 - 1997-12-31)) | dimensionalize(customer.customer_key);
dimension customer.is_lapsed = coalesce(customer.orders_1996, 0) > 0 and coalesce(customer.orders_1997, 0) == 0;
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    lapsed_customer_count: customer_count,
    lapsed_revenue_1996: coalesce(revenue | where(orders.order_date matches @(1996-01-01 - 1996-12-31)), 0),
  }
  filters { customer.is_lapsed is true }
  sorts { market_segment asc }
}

metric brand_rank = rank(
  order: revenue | desc(),
  order: part | min(part.brand) | asc(),
  partition: customer_region.customer_region_name
);
explore {
  dimensions {
    customer_region_name: customer_region.customer_region_name,
    brand: part.brand,
  }
  measures {
    revenue: revenue,
    brand_rank: brand_rank,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  having { brand_rank < 4 }
  sorts { customer_region_name asc, brand_rank asc }
}

dimension customer.lifetime_orders = order_count | dimensionalize(customer.customer_key);
dimension customer.order_count_bucket = case(
  when: customer.lifetime_orders < 10, then: '1-9',
  when: customer.lifetime_orders < 15, then: '10-14',
  when: customer.lifetime_orders < 20, then: '15-19',
  when: customer.lifetime_orders < 25, then: '20-24',
  else: '25+'
);
explore {
  dimensions { order_count_bucket: customer.order_count_bucket }
  measures { customer_count: customer_count, revenue: revenue }
  filters { customer.lifetime_orders > 0 }
  sorts { order_count_bucket asc }
}

metric revenue_1993 = revenue | where(orders.order_date matches @(1993-01-01 - 1993-12-31));
metric revenue_1997 = revenue | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
metric revenue_share_1993 = revenue_1993 / (revenue_1993 | exclude_grains(customer.market_segment));
metric revenue_share_1997 = revenue_1997 / (revenue_1997 | exclude_grains(customer.market_segment));
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    revenue_share_1993: revenue_share_1993,
    revenue_share_1997: revenue_share_1997,
    share_change: revenue_share_1997 - revenue_share_1993,
  }
  sorts { market_segment asc }
}

metric revenue_1997 = revenue | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
dimension supplier.revenue_1997 = revenue_1997 | dimensionalize(supplier.supplier_key);
dimension supplier.cumulative_revenue_1997 = window_sum(
  revenue_1997,
  order: revenue_1997 | desc(),
  order: supplier | min(supplier.supplier_key) | asc(),
  partition: []
);
dimension supplier.total_revenue_1997 = revenue_1997 | dimensionalize();
dimension supplier.needed_for_80pct = supplier.cumulative_revenue_1997 - supplier.revenue_1997 < 0.8 * supplier.total_revenue_1997;
metric active_supplier_count = supplier_count | where(supplier.revenue_1997 is not null);
metric suppliers_for_80pct_revenue = supplier_count | where(supplier.revenue_1997 is not null) | where(supplier.needed_for_80pct is true);
explore {
  measures {
    active_supplier_count: active_supplier_count,
    suppliers_for_80pct_revenue: suppliers_for_80pct_revenue,
    supplier_share_for_80pct: suppliers_for_80pct_revenue / active_supplier_count,
  }
}

dimension lineitem.transit_days = date_diff('day', lineitem.ship_date, lineitem.receipt_date);
explore {
  dimensions { ship_mode: lineitem.ship_mode }
  measures {
    line_count: line_count,
    median_transit_days: lineitem | percentile_cont(lineitem.transit_days, 0.5),
    p90_transit_days: lineitem | percentile_cont(lineitem.transit_days, 0.9),
  }
  filters { lineitem.ship_date matches @(1997-01-01 - 1997-12-31) }
  sorts { ship_mode asc }
}

dimension orders.late_lines = lineitem | count_if(lineitem.receipt_date > lineitem.commit_date) | dimensionalize(orders.order_key);
explore {
  dimensions {
    order_year: orders.order_date | year(),
    order_priority: orders.order_priority,
  }
  measures {
    order_count: order_count,
    perfect_order_share: (order_count | where(coalesce(orders.late_lines, 0) == 0)) / order_count,
  }
  filters { orders.order_date matches @(1993-01-01 - 1997-12-31) }
  sorts { order_year asc, order_priority asc }
}

metric avg_promised_days = lineitem | avg(date_diff('day', orders.order_date, lineitem.commit_date));
metric avg_actual_days = lineitem | avg(date_diff('day', orders.order_date, lineitem.receipt_date));
explore {
  dimensions { order_priority: orders.order_priority }
  measures {
    avg_promised_days: avg_promised_days,
    avg_actual_days: avg_actual_days,
    avg_gap_days: avg_actual_days - avg_promised_days,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { order_priority asc }
}

metric late_lines = lineitem | count_if(lineitem.receipt_date > lineitem.commit_date);
explore {
  dimensions { ship_month: lineitem.ship_date | month() }
  measures {
    late_share: late_lines / line_count,
    rolling_3m_late_share: (late_lines | trailing_period(lineitem.ship_date, interval(3 months)))
      / (line_count | trailing_period(lineitem.ship_date, interval(3 months))),
  }
  filters { lineitem.ship_date matches @(1996-01-01 - 1997-12-31) }
  sorts { ship_month asc }
}

metric returned_share = (lineitem | count_if(lineitem.return_flag == 'R')) / line_count;
explore {
  dimensions {
    ship_mode: lineitem.ship_mode,
    ship_instruct: lineitem.ship_instruct,
  }
  measures {
    line_count: line_count,
    returned_share: returned_share,
    return_rate_index: returned_share / (returned_share | exclude_grains(lineitem.ship_mode, lineitem.ship_instruct)),
  }
  filters { lineitem.receipt_date matches @(1993-01-01 - 1994-12-31) }
  sorts { ship_mode asc, ship_instruct asc }
}

metric lines_1997 = line_count | where(lineitem.ship_date matches @(1997-01-01 - 1997-12-31));
metric late_lines_1997 = lineitem | count_if(lineitem.receipt_date > lineitem.commit_date) | where(lineitem.ship_date matches @(1997-01-01 - 1997-12-31));
metric late_share_1997 = late_lines_1997 / lines_1997;
dimension supplier.lines_1997 = lines_1997 | dimensionalize(supplier.supplier_key);
dimension supplier.late_share_1997 = late_share_1997 | dimensionalize(supplier.supplier_key);
dimension supplier.region_late_share_1997 = late_share_1997 | dimensionalize(supplier_region.supplier_region_name);
dimension supplier.is_outlier = supplier.late_share_1997 >= supplier.region_late_share_1997 + 0.10;
metric qualifying_supplier_count = supplier_count | where(supplier.lines_1997 > 49);
metric outlier_supplier_count = coalesce(qualifying_supplier_count | where(supplier.is_outlier is true), 0);
explore {
  dimensions { supplier_region_name: supplier_region.supplier_region_name }
  measures {
    region_late_share: late_share_1997,
    qualifying_supplier_count: qualifying_supplier_count,
    outlier_supplier_count: outlier_supplier_count,
    outlier_share: outlier_supplier_count / qualifying_supplier_count,
  }
  sorts { supplier_region_name asc }
}

dimension orders.line_items = line_count | dimensionalize(orders.order_key);
dimension orders.first_ship_date = lineitem | min(lineitem.ship_date) | dimensionalize(orders.order_key);
dimension orders.last_ship_date = lineitem | max(lineitem.ship_date) | dimensionalize(orders.order_key);
dimension orders.ship_span_days = date_diff('day', orders.first_ship_date, orders.last_ship_date);
explore {
  dimensions { order_priority: orders.order_priority }
  measures {
    order_count: order_count,
    median_ship_span_days: orders | percentile_cont(orders.ship_span_days, 0.5),
    p90_ship_span_days: orders | percentile_cont(orders.ship_span_days, 0.9),
  }
  filters {
    orders.order_date matches @(1996-01-01 - 1996-12-31),
    orders.line_items > 1,
  }
  sorts { order_priority asc }
}

metric revenue_1996 = revenue | where(orders.order_date matches @(1996-01-01 - 1996-12-31));
metric revenue_1997 = revenue | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
metric quantity_1996 = total_quantity | where(orders.order_date matches @(1996-01-01 - 1996-12-31));
metric quantity_1997 = total_quantity | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
explore {
  dimensions { manufacturer: part.manufacturer }
  measures {
    revenue_1996: revenue_1996,
    revenue_1997: revenue_1997,
    revenue_change: revenue_1997 - revenue_1996,
    volume_effect: (quantity_1997 - quantity_1996) * (revenue_1996 / quantity_1996),
    price_effect: (revenue_1997 / quantity_1997 - revenue_1996 / quantity_1996) * quantity_1997,
  }
  sorts { manufacturer asc }
}

metric revenue_1997 = revenue | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
metric supply_cost_1997 = lineitem | sum(partsupp.supply_cost * lineitem.quantity) | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
dimension customer.orders_1997 = order_count | where(orders.order_date matches @(1997-01-01 - 1997-12-31)) | dimensionalize(customer.customer_key);
dimension customer.margin_rate_1997 = (revenue_1997 - supply_cost_1997) / revenue_1997 | dimensionalize(customer.customer_key);
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    customer_count: customer_count,
    p25_margin_rate: customer | percentile_cont(customer.margin_rate_1997, 0.25),
    median_margin_rate: customer | percentile_cont(customer.margin_rate_1997, 0.5),
    p75_margin_rate: customer | percentile_cont(customer.margin_rate_1997, 0.75),
  }
  filters { customer.orders_1997 > 2 }
  sorts { market_segment asc }
}

metric ytd_revenue = revenue | period_to_date('year', orders.order_date);
explore {
  dimensions { order_month: orders.order_date | month() }
  measures {
    ytd_revenue_1998: ytd_revenue,
    ytd_revenue_1997: ytd_revenue | relative_period(orders.order_date, interval(-1 year)),
    ytd_growth: ytd_revenue / (ytd_revenue | relative_period(orders.order_date, interval(-1 year))) - 1,
  }
  filters { orders.order_date matches @(1998-01-01 - 1998-07-31) }
  sorts { order_month asc }
}

metric supply_cost_amount = lineitem | sum(partsupp.supply_cost * lineitem.quantity);
metric margin = revenue - supply_cost_amount;
metric margin_rank = rank(
  order: margin | desc(),
  order: customer | min(customer.customer_key) | asc(),
  partition: []
);
explore {
  dimensions {
    customer_key: customer.customer_key,
    customer_name: customer.customer_name,
  }
  measures {
    margin_rank: margin_rank,
    margin: margin,
    margin_rate: margin / revenue,
    cumulative_margin_share: window_sum(margin, order: margin | desc(), order: customer | min(customer.customer_key) | asc(), partition: [])
      / (margin | exclude_grains(customer.customer_key, customer.customer_name)),
  }
  having { margin_rank < 21 }
  sorts { margin_rank asc }
}

metric ttm_revenue = revenue | trailing_period(orders.order_date, interval(12 months));
explore {
  dimensions { order_month: orders.order_date | month() }
  measures {
    ttm_revenue: ttm_revenue,
    ttm_revenue_prior_year: ttm_revenue | relative_period(orders.order_date, interval(-1 year)),
    ttm_growth: ttm_revenue / (ttm_revenue | relative_period(orders.order_date, interval(-1 year))) - 1,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { order_month asc }
}

dimension orders.large_order_threshold_1997 = orders | percentile_cont(orders.total_price, 0.9) | where(orders.order_date matches @(1997-01-01 - 1997-12-31)) | dimensionalize();
dimension orders.is_large = orders.total_price > orders.large_order_threshold_1997;
explore {
  dimensions { customer_region_name: customer_region.customer_region_name }
  measures {
    large_order_threshold: orders | max(orders.large_order_threshold_1997),
    order_value: order_value,
    large_order_count: order_count | where(orders.is_large is true),
    large_order_value_share: (order_value | where(orders.is_large is true)) / order_value,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { customer_region_name asc }
}

dimension part.min_supply_cost = partsupp | min(partsupp.supply_cost) | dimensionalize(part.part_name, part.manufacturer);
metric actual_cost = lineitem | sum(partsupp.supply_cost * lineitem.quantity);
metric cheapest_cost = lineitem | sum(part.min_supply_cost * lineitem.quantity);
explore {
  dimensions { manufacturer: part.manufacturer }
  measures {
    actual_cost: actual_cost,
    cheapest_cost: cheapest_cost,
    savings_opportunity: actual_cost - cheapest_cost,
    savings_share: (actual_cost - cheapest_cost) / actual_cost,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { manufacturer asc }
}

metric supply_cost_amount = lineitem | sum(partsupp.supply_cost * lineitem.quantity);
explore {
  dimensions { order_priority: orders.order_priority }
  measures {
    avg_discount: avg_discount,
    revenue: revenue,
    margin_rate: (revenue - supply_cost_amount) / revenue,
  }
  filters { orders.order_date matches @(1997-01-01 - 1997-12-31) }
  sorts { order_priority asc }
}

dimension orders.is_1997 = orders.order_date matches @(1997-01-01 - 1997-12-31);
metric decile_within_year_flag = ntile(10,
  order: orders | max(orders.total_price) | desc(),
  order: orders | min(orders.order_key) | asc(),
  partition: orders.is_1997
);
dimension orders.value_decile = decile_within_year_flag;
explore {
  dimensions { value_decile: orders.value_decile }
  measures {
    order_count: order_count,
    order_value: order_value,
    order_value_share: order_value / (order_value | exclude_grains(orders.value_decile)),
    min_total_price: orders | min(orders.total_price),
    max_total_price: orders | max(orders.total_price),
  }
  filters { orders.is_1997 is true }
  sorts { value_decile asc }
}

dimension customer.first_order_date = orders | min(orders.order_date) | dimensionalize(customer.customer_key);
dimension customer.first_order_year = date_part('year', customer.first_order_date);
dimension orders.is_first_year = date_part('year', orders.order_date) == customer.first_order_year;
explore {
  dimensions {
    first_order_year: customer.first_order_year,
    order_year: orders.order_date | year(),
  }
  measures {
    revenue: revenue,
    revenue_index: revenue / (revenue | where(orders.is_first_year is true) | keep_grains(customer.first_order_year)),
  }
  filters {
    customer.first_order_year in [1992, 1993, 1994, 1995],
    orders.order_date matches @(1992-01-01 - 1997-12-31),
  }
  sorts { first_order_year asc, order_year asc }
}

metric order_position = rank(
  order: orders | min(orders.order_date) | asc(),
  order: orders | min(orders.order_key) | asc(),
  partition: customer.customer_key
);
dimension orders.position = order_position;
dimension customer.first_order_date = orders | where(orders.position == 1) | min(orders.order_date) | dimensionalize(customer.customer_key);
dimension customer.second_order_date = orders | where(orders.position == 2) | min(orders.order_date) | dimensionalize(customer.customer_key);
dimension customer.days_to_second_order = date_diff('day', customer.first_order_date, customer.second_order_date);
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    customer_count: customer_count,
    median_days_to_second_order: customer | percentile_cont(customer.days_to_second_order, 0.5),
    p90_days_to_second_order: customer | percentile_cont(customer.days_to_second_order, 0.9),
  }
  filters { customer.second_order_date is not null }
  sorts { market_segment asc }
}

dimension customer.orders_1994 = order_count | where(orders.order_date matches @(1994-01-01 - 1994-12-31)) | dimensionalize(customer.customer_key);
dimension customer.orders_1995 = order_count | where(orders.order_date matches @(1995-01-01 - 1995-12-31)) | dimensionalize(customer.customer_key);
dimension customer.orders_1996_1997 = order_count | where(orders.order_date matches @(1996-01-01 - 1997-12-31)) | dimensionalize(customer.customer_key);
dimension customer.is_lapsed = coalesce(customer.orders_1994, 0) > 0 and coalesce(customer.orders_1995, 0) == 0;
dimension customer.is_reactivated = coalesce(customer.orders_1996_1997, 0) > 0;
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    lapsed_customer_count: customer_count,
    reactivated_customer_count: customer_count | where(customer.is_reactivated is true),
    reactivation_share: (customer_count | where(customer.is_reactivated is true)) / customer_count,
  }
  filters { customer.is_lapsed is true }
  sorts { market_segment asc }
}

metric order_position = rank(
  order: orders | min(orders.order_date) | asc(),
  order: orders | min(orders.order_key) | asc(),
  partition: customer.customer_key
);
dimension orders.position = order_position;
metric first_order_avg_value = orders | where(orders.position == 1) | avg(orders.total_price);
metric repeat_order_avg_value = orders | where(orders.position > 1) | avg(orders.total_price);
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    first_order_avg_value: first_order_avg_value,
    repeat_order_avg_value: repeat_order_avg_value,
    first_to_repeat_ratio: first_order_avg_value / repeat_order_avg_value,
  }
  sorts { market_segment asc }
}

metric revenue_1996 = revenue | where(orders.order_date matches @(1996-01-01 - 1996-12-31));
metric revenue_1997 = revenue | where(orders.order_date matches @(1997-01-01 - 1997-12-31));
dimension customer.revenue_1996 = revenue_1996 | dimensionalize(customer.customer_key);
dimension customer.revenue_1997 = revenue_1997 | dimensionalize(customer.customer_key);
dimension customer.in_both_years = customer.revenue_1996 is not null and customer.revenue_1997 is not null;
metric quartile_1996 = ntile(4,
  order: revenue_1996 | desc(),
  order: customer | min(customer.customer_key) | asc(),
  partition: customer.in_both_years
);
metric quartile_1997 = ntile(4,
  order: revenue_1997 | desc(),
  order: customer | min(customer.customer_key) | asc(),
  partition: customer.in_both_years
);
dimension customer.revenue_quartile_1996 = quartile_1996;
dimension customer.revenue_quartile_1997 = quartile_1997;
explore {
  dimensions {
    revenue_quartile_1996: customer.revenue_quartile_1996,
    revenue_quartile_1997: customer.revenue_quartile_1997,
  }
  measures { customer_count: customer | count(customer.customer_key) }
  filters { customer.in_both_years is true }
  sorts { revenue_quartile_1996 asc, revenue_quartile_1997 asc }
}

dimension customer.lifetime_orders = order_count | dimensionalize(customer.customer_key);
explore {
  dimensions { market_segment: customer.market_segment }
  measures {
    never_ordered_count: customer_count | where(customer.lifetime_orders is null),
    never_ordered_share: (customer_count | where(customer.lifetime_orders is null)) / customer_count,
    avg_balance_never_ordered: customer | where(customer.lifetime_orders is null) | avg(customer.account_balance),
    avg_balance_ordered: customer | where(customer.lifetime_orders is not null) | avg(customer.account_balance),
  }
  sorts { market_segment asc }
}

dimension customer.brands_1997 = lineitem | count_distinct(part.brand) | where(orders.order_date matches @(1997-01-01 - 1997-12-31)) | dimensionalize(customer.customer_key);
dimension customer.brand_count_bucket = case(
  when: customer.brands_1997 < 3, then: '1-2',
  when: customer.brands_1997 < 6, then: '3-5',
  when: customer.brands_1997 < 11, then: '6-10',
  else: '11+'
);
explore {
  dimensions { brand_count_bucket: customer.brand_count_bucket }
  measures {
    customer_count: customer_count,
    avg_revenue_per_customer: revenue / customer_count,
    revenue_share: revenue / (revenue | exclude_grains(customer.brand_count_bucket)),
  }
  filters {
    orders.order_date matches @(1997-01-01 - 1997-12-31),
    customer.brands_1997 > 0,
  }
  sorts { brand_count_bucket asc }
}
